import { app, BrowserWindow, ipcMain, session, shell } from 'electron';
import fs from 'fs';
import path from 'path';
import { startServer } from './server/server';
import { APPS_PATH } from './server/constants/paths';
import logger from './server/utils/logger';
import type { StartupState } from './types/startup';

// This allows TypeScript to pick up the magic constants that's auto-generated by Forge's Webpack
// plugin that tells the Electron app where to look for the Webpack-bundled app code (depending on
// whether you're running in development or production).
declare const MAIN_WINDOW_WEBPACK_ENTRY: string;
declare const MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY: string;

const LOOPBACK_HOSTS = ['localhost', '127.0.0.1'];

// Handle creating/removing shortcuts on Windows when installing/uninstalling.
// eslint-disable-next-line @typescript-eslint/no-require-imports
const isSquirrelStartup: boolean = require('electron-squirrel-startup');
if (isSquirrelStartup) {
  app.quit();
}

let serverUrl: string | null = null;
let serverError: string | null = null;

// Start the local API / static server; windows wait on this before loading
const serverReady = isSquirrelStartup
  ? Promise.resolve()
  : startServer()
    .then((port) => {
      serverUrl = `http://localhost:${port}`;
    })
    .catch((error: Error) => {
      serverError = error.message;
      logger.error(`Failed to start server: ${error.message}`);
    });

const getStartupState = (): StartupState => {
  if (!serverUrl) {
    return { status: 'server-error', message: serverError ?? 'The local server did not start.' };
  }
  if (!fs.existsSync(path.join(APPS_PATH, 'index.html'))) {
    return { status: 'no-app', serverUrl, appsPath: APPS_PATH };
  }
  return { status: 'ready', serverUrl };
};

/**
 * Load the shell application if it is installed, otherwise the bundled status screen.
 */
const loadContent = (window: BrowserWindow): void => {
  const state = getStartupState();
  const url = state.status === 'ready' ? `${state.serverUrl}/` : MAIN_WINDOW_WEBPACK_ENTRY;
  window.loadURL(url).catch((error: Error) => logger.error(`Failed to load ${url}: ${error.message}`));
};

const isInternalUrl = (url: string): boolean => {
  const { protocol, hostname } = new URL(url);
  return protocol === 'file:' || LOOPBACK_HOSTS.includes(hostname);
};

const openExternally = (url: string): void => {
  if (/^https?:/.test(url)) {
    shell.openExternal(url);
  }
};

const createWindow = async (): Promise<void> => {
  await serverReady;

  const mainWindow = new BrowserWindow({
    height: 600,
    width: 800,
    autoHideMenuBar: true,
    webPreferences: {
      preload: MAIN_WINDOW_PRELOAD_WEBPACK_ENTRY,
    },
  });

  // Keep the window on local content; send everything else to the default browser
  mainWindow.webContents.setWindowOpenHandler(({ url }) => {
    openExternally(url);
    return { action: 'deny' };
  });
  mainWindow.webContents.on('will-navigate', (event, url) => {
    if (!isInternalUrl(url)) {
      event.preventDefault();
      openExternally(url);
    }
  });

  loadContent(mainWindow);

  if (!app.isPackaged) {
    mainWindow.webContents.openDevTools();
  }
};

const setContentSecurityPolicy = (): void => {
  session.defaultSession.webRequest.onHeadersReceived((details, callback) => {
    callback({
      responseHeaders: {
        ...details.responseHeaders,
        'Content-Security-Policy': [
          "frame-src 'self' http://localhost:* http://127.0.0.1:*; " +
          "style-src 'self' 'unsafe-inline'; " +
          "connect-src 'self' http://localhost:* http://127.0.0.1:*;"
        ]
      }
    });
  });
};

// This method will be called when Electron has finished
// initialization and is ready to create browser windows.
// Some APIs can only be used after this event occurs.
app.whenReady().then(() => {
  setContentSecurityPolicy();
  return createWindow();
});

// Quit when all windows are closed, except on macOS. There, it's common
// for applications and their menu bar to stay active until the user quits
// explicitly with Cmd + Q.
app.on('window-all-closed', () => {
  if (process.platform !== 'darwin') {
    app.quit();
  }
});

app.on('activate', () => {
  // On OS X it's common to re-create a window in the app when the
  // dock icon is clicked and there are no other windows open.
  if (BrowserWindow.getAllWindows().length === 0) {
    createWindow();
  }
});

ipcMain.handle('get-server-address', () => (serverUrl ? `${serverUrl}/` : null));

ipcMain.handle('get-startup-state', () => getStartupState());

ipcMain.handle('retry-startup', (event) => {
  const window = BrowserWindow.fromWebContents(event.sender);
  if (window) {
    loadContent(window);
  }
});

ipcMain.handle('open-apps-folder', () => shell.openPath(APPS_PATH));
